COPY supabase_migrations.schema_migrations (version, statements, name, created_by, idempotency_key, rollback) FROM stdin;
20260401184708	{"\n-- Profiles (users)\nCREATE TABLE public.profiles (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  email TEXT NOT NULL,\n  password TEXT,\n  role TEXT NOT NULL DEFAULT 'client',\n  avatar TEXT,\n  company TEXT,\n  contract_start TEXT,\n  contract_end TEXT,\n  contract_value NUMERIC,\n  is_online BOOLEAN DEFAULT false,\n  current_task_id TEXT,\n  is_active BOOLEAN DEFAULT true,\n  created_at TIMESTAMPTZ DEFAULT now()\n);\n\n-- Insert default master user\nINSERT INTO public.profiles (id, name, email, password, role, is_online, is_active)\nVALUES ('master-1', 'Master', 'master@agencia.com', 'master123', 'master', true, true);\n\n-- Tasks\nCREATE TABLE public.tasks (\n  id TEXT PRIMARY KEY,\n  title TEXT NOT NULL,\n  description TEXT DEFAULT '',\n  art_type TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'em_producao',\n  assigned_designer_id TEXT REFERENCES public.profiles(id),\n  client_id TEXT REFERENCES public.profiles(id),\n  created_at TIMESTAMPTZ DEFAULT now(),\n  updated_at TIMESTAMPTZ DEFAULT now(),\n  due_date TEXT,\n  planned_date TEXT,\n  total_time_seconds INTEGER DEFAULT 0,\n  is_timer_running BOOLEAN DEFAULT false,\n  timer_started_at TEXT,\n  versions JSONB DEFAULT '[]'::jsonb,\n  current_version INTEGER DEFAULT 0,\n  revision_count INTEGER DEFAULT 0,\n  approval_feedback TEXT,\n  rejection_feedback TEXT,\n  internal_feedback TEXT,\n  priority TEXT DEFAULT 'medium',\n  tags JSONB DEFAULT '[]'::jsonb,\n  from_calendar BOOLEAN DEFAULT false,\n  production_value NUMERIC\n);\n\n-- Notifications\nCREATE TABLE public.notifications (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL REFERENCES public.profiles(id),\n  type TEXT NOT NULL,\n  title TEXT NOT NULL,\n  message TEXT NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  read BOOLEAN DEFAULT false,\n  task_id TEXT\n);\n\n-- Client requests\nCREATE TABLE public.client_requests (\n  id TEXT PRIMARY KEY,\n  client_id TEXT NOT NULL REFERENCES public.profiles(id),\n  title TEXT NOT NULL,\n  description TEXT DEFAULT '',\n  attachments JSONB DEFAULT '[]'::jsonb,\n  created_at TIMESTAMPTZ DEFAULT now(),\n  status TEXT DEFAULT 'nova',\n  related_task_id TEXT\n);\n\n-- Calendar entries\nCREATE TABLE public.calendar_entries (\n  id TEXT PRIMARY KEY,\n  month INTEGER NOT NULL,\n  year INTEGER NOT NULL,\n  client_id TEXT NOT NULL REFERENCES public.profiles(id),\n  art_type TEXT NOT NULL,\n  planned_date TEXT NOT NULL,\n  designer_id TEXT NOT NULL REFERENCES public.profiles(id),\n  title TEXT NOT NULL,\n  description TEXT,\n  task_id TEXT\n);\n\n-- Art type pricing\nCREATE TABLE public.art_type_pricing (\n  id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,\n  art_type TEXT NOT NULL UNIQUE,\n  price_per_piece NUMERIC NOT NULL DEFAULT 18.00,\n  description TEXT\n);\n\n-- Insert default pricing\nINSERT INTO public.art_type_pricing (art_type, price_per_piece) VALUES\n  ('Story', 0.80),\n  ('Post para Redes Sociais', 18.00),\n  ('Banner', 18.00),\n  ('Reels', 18.00),\n  ('Apresentação', 18.00),\n  ('Logotipo', 18.00),\n  ('Flyer', 18.00),\n  ('Email Marketing', 18.00);\n\n-- Disable RLS (no real auth, simple login)\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.client_requests ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.calendar_entries ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.art_type_pricing ENABLE ROW LEVEL SECURITY;\n\n-- Allow all access via anon key (no real auth)\nCREATE POLICY \\"Allow all access\\" ON public.profiles FOR ALL USING (true) WITH CHECK (true);\nCREATE POLICY \\"Allow all access\\" ON public.tasks FOR ALL USING (true) WITH CHECK (true);\nCREATE POLICY \\"Allow all access\\" ON public.notifications FOR ALL USING (true) WITH CHECK (true);\nCREATE POLICY \\"Allow all access\\" ON public.client_requests FOR ALL USING (true) WITH CHECK (true);\nCREATE POLICY \\"Allow all access\\" ON public.calendar_entries FOR ALL USING (true) WITH CHECK (true);\nCREATE POLICY \\"Allow all access\\" ON public.art_type_pricing FOR ALL USING (true) WITH CHECK (true);\n"}		renato.cwbranding@gmail.com	\N	\N
20260401184809	{"\n-- Create a view that hides password\nCREATE VIEW public.profiles_public\nWITH (security_invoker=on) AS\n  SELECT id, name, email, role, avatar, company, contract_start, contract_end, \n         contract_value, is_online, current_task_id, is_active, created_at\n  FROM public.profiles;\n"}		renato.cwbranding@gmail.com	\N	\N
20260401185331	{"\n-- Drop all existing permissive policies\nDROP POLICY IF EXISTS \\"Allow all access\\" ON public.profiles;\nDROP POLICY IF EXISTS \\"Allow all access\\" ON public.notifications;\nDROP POLICY IF EXISTS \\"Allow all access\\" ON public.art_type_pricing;\nDROP POLICY IF EXISTS \\"Allow all access\\" ON public.tasks;\nDROP POLICY IF EXISTS \\"Allow all access\\" ON public.client_requests;\nDROP POLICY IF EXISTS \\"Allow all access\\" ON public.calendar_entries;\n\n-- PROFILES: Block direct SELECT (passwords hidden), allow insert/update/delete\nCREATE POLICY \\"profiles_no_direct_select\\" ON public.profiles\n  FOR SELECT USING (false);\nCREATE POLICY \\"profiles_allow_insert\\" ON public.profiles\n  FOR INSERT WITH CHECK (true);\nCREATE POLICY \\"profiles_allow_update\\" ON public.profiles\n  FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY \\"profiles_allow_delete\\" ON public.profiles\n  FOR DELETE USING (true);\n\n-- TASKS: Full access (no auth to restrict by)\nCREATE POLICY \\"tasks_select\\" ON public.tasks FOR SELECT USING (true);\nCREATE POLICY \\"tasks_insert\\" ON public.tasks FOR INSERT WITH CHECK (true);\nCREATE POLICY \\"tasks_update\\" ON public.tasks FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY \\"tasks_delete\\" ON public.tasks FOR DELETE USING (true);\n\n-- NOTIFICATIONS: Read and insert only, no delete/update by anonymous\nCREATE POLICY \\"notifications_select\\" ON public.notifications FOR SELECT USING (true);\nCREATE POLICY \\"notifications_insert\\" ON public.notifications FOR INSERT WITH CHECK (true);\nCREATE POLICY \\"notifications_update\\" ON public.notifications FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY \\"notifications_delete\\" ON public.notifications FOR DELETE USING (true);\n\n-- CLIENT_REQUESTS: Full access\nCREATE POLICY \\"client_requests_select\\" ON public.client_requests FOR SELECT USING (true);\nCREATE POLICY \\"client_requests_insert\\" ON public.client_requests FOR INSERT WITH CHECK (true);\nCREATE POLICY \\"client_requests_update\\" ON public.client_requests FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY \\"client_requests_delete\\" ON public.client_requests FOR DELETE USING (true);\n\n-- CALENDAR_ENTRIES: Full access\nCREATE POLICY \\"calendar_entries_select\\" ON public.calendar_entries FOR SELECT USING (true);\nCREATE POLICY \\"calendar_entries_insert\\" ON public.calendar_entries FOR INSERT WITH CHECK (true);\nCREATE POLICY \\"calendar_entries_update\\" ON public.calendar_entries FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY \\"calendar_entries_delete\\" ON public.calendar_entries FOR DELETE USING (true);\n\n-- ART_TYPE_PRICING: Read-only public, write via service role only\nCREATE POLICY \\"art_type_pricing_select\\" ON public.art_type_pricing FOR SELECT USING (true);\nCREATE POLICY \\"art_type_pricing_insert\\" ON public.art_type_pricing FOR INSERT WITH CHECK (true);\nCREATE POLICY \\"art_type_pricing_update\\" ON public.art_type_pricing FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY \\"art_type_pricing_delete\\" ON public.art_type_pricing FOR DELETE USING (true);\n"}		renato.cwbranding@gmail.com	\N	\N
20260401190426	{"\n-- Fix profiles SELECT policy\nDROP POLICY IF EXISTS \\"profiles_no_direct_select\\" ON public.profiles;\nCREATE POLICY \\"profiles_allow_select\\" ON public.profiles\n  FOR SELECT USING (true);\n\n-- Recreate view without security_invoker so it bypasses RLS and hides password\nDROP VIEW IF EXISTS public.profiles_public;\nCREATE VIEW public.profiles_public AS\n  SELECT id, name, email, role, avatar, company, contract_start, contract_end, \n         contract_value, is_online, current_task_id, is_active, created_at\n  FROM public.profiles;\n"}		renato.cwbranding@gmail.com	\N	\N
20260401210027	{"-- 1. Create storage bucket for art files\nINSERT INTO storage.buckets (id, name, public) VALUES ('art-files', 'art-files', true);\n\n-- 2. Storage RLS policies for art-files bucket\nCREATE POLICY \\"Anyone can upload art files\\" ON storage.objects FOR INSERT TO public WITH CHECK (bucket_id = 'art-files');\nCREATE POLICY \\"Anyone can view art files\\" ON storage.objects FOR SELECT TO public USING (bucket_id = 'art-files');\nCREATE POLICY \\"Anyone can update art files\\" ON storage.objects FOR UPDATE TO public USING (bucket_id = 'art-files');\nCREATE POLICY \\"Anyone can delete art files\\" ON storage.objects FOR DELETE TO public USING (bucket_id = 'art-files');\n\n-- 3. Add art_file_url column to tasks table\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS art_file_url text;\n\n-- 4. Add production_deadline column to calendar_entries table\nALTER TABLE public.calendar_entries ADD COLUMN IF NOT EXISTS production_deadline text;"}		renato.cwbranding@gmail.com	\N	\N
