20260402201622	{"CREATE TABLE public.client_reports (\n  id text NOT NULL DEFAULT (gen_random_uuid())::text PRIMARY KEY,\n  client_id text NOT NULL,\n  title text NOT NULL,\n  file_url text NOT NULL,\n  file_type text NOT NULL DEFAULT 'pdf',\n  uploaded_by text NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.client_reports ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"client_reports_select\\" ON public.client_reports FOR SELECT TO public USING (true);\nCREATE POLICY \\"client_reports_insert\\" ON public.client_reports FOR INSERT TO public WITH CHECK (true);\nCREATE POLICY \\"client_reports_update\\" ON public.client_reports FOR UPDATE TO public USING (true) WITH CHECK (true);\nCREATE POLICY \\"client_reports_delete\\" ON public.client_reports FOR DELETE TO public USING (true);"}		renato.cwbranding@gmail.com	\N	\N
