20260507195917	{"\nCREATE TABLE public.agenda_events (\n  id text PRIMARY KEY DEFAULT (gen_random_uuid())::text,\n  title text NOT NULL,\n  description text DEFAULT '',\n  event_date text NOT NULL,\n  start_time text,\n  end_time text,\n  event_type text NOT NULL DEFAULT 'reuniao',\n  recurrence text NOT NULL DEFAULT 'nenhuma',\n  participants jsonb NOT NULL DEFAULT '[]'::jsonb,\n  meeting_link text,\n  location text,\n  priority text NOT NULL DEFAULT 'media',\n  status text NOT NULL DEFAULT 'agendado',\n  created_by text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.agenda_events ENABLE ROW LEVEL SECURITY;\nCREATE POLICY agenda_events_select ON public.agenda_events FOR SELECT USING (true);\nCREATE POLICY agenda_events_insert ON public.agenda_events FOR INSERT WITH CHECK (true);\nCREATE POLICY agenda_events_update ON public.agenda_events FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY agenda_events_delete ON public.agenda_events FOR DELETE USING (true);\n\nCREATE TABLE public.agenda_confirmations (\n  id text PRIMARY KEY DEFAULT (gen_random_uuid())::text,\n  event_id text NOT NULL,\n  user_id text NOT NULL,\n  confirmed_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(event_id, user_id)\n);\n\nALTER TABLE public.agenda_confirmations ENABLE ROW LEVEL SECURITY;\nCREATE POLICY agenda_confirmations_select ON public.agenda_confirmations FOR SELECT USING (true);\nCREATE POLICY agenda_confirmations_insert ON public.agenda_confirmations FOR INSERT WITH CHECK (true);\nCREATE POLICY agenda_confirmations_update ON public.agenda_confirmations FOR UPDATE USING (true) WITH CHECK (true);\nCREATE POLICY agenda_confirmations_delete ON public.agenda_confirmations FOR DELETE USING (true);\n\nCREATE INDEX idx_agenda_events_date ON public.agenda_events(event_date);\nCREATE INDEX idx_agenda_confirmations_event ON public.agenda_confirmations(event_id);\n"}		renato.cwbranding@gmail.com	\N	\N
