20260511123616	{"\n-- Remove the permissive public SELECT policy that exposed passwords + contracts\nDROP POLICY IF EXISTS profiles_allow_select ON public.profiles;\n\n-- Block anon role entirely from reading the raw profiles table.\n-- The app reads via the public view `profiles_public` (no password/contract columns),\n-- and the verify-login edge function uses the service role to check passwords.\nREVOKE SELECT ON public.profiles FROM anon;\nREVOKE SELECT ON public.profiles FROM authenticated;\n\n-- Keep service_role full access (used by edge functions)\nGRANT SELECT ON public.profiles TO service_role;\n"}		renato.cwbranding@gmail.com	\N	\N
20260521121952	{"-- Repair calendar_entries that were mis-linked by the title-only matching bug.\n-- 1) Re-link each calendar entry to the task whose id encodes its own entry id.\nUPDATE calendar_entries ce\nSET task_id = t.id\nFROM tasks t\nWHERE t.id LIKE 'task-cal-' || ce.id || '-%'\n  AND (ce.task_id IS NULL OR ce.task_id <> t.id);\n\n-- 2) For entries whose corresponding task no longer exists, clear the bad link\n--    so they can be regenerated cleanly from the Kanban flow.\nUPDATE calendar_entries ce\nSET task_id = NULL\nWHERE ce.task_id IS NOT NULL\n  AND NOT EXISTS (SELECT 1 FROM tasks t WHERE t.id = ce.task_id);\n\n-- 3) Remove exact duplicate calendar entries (same client+title+planned_date),\n--    keeping the one that is correctly linked to a task (or the oldest id otherwise).\nDELETE FROM calendar_entries ce\nUSING calendar_entries keep\nWHERE ce.client_id = keep.client_id\n  AND ce.title = keep.title\n  AND ce.planned_date = keep.planned_date\n  AND ce.id <> keep.id\n  AND (\n    (keep.task_id IS NOT NULL AND ce.task_id IS NULL)\n    OR (keep.task_id IS NOT NULL AND ce.task_id IS NOT NULL AND keep.id < ce.id)\n    OR (keep.task_id IS NULL AND ce.task_id IS NULL AND keep.id < ce.id)\n  );"}		renato.cwbranding@gmail.com	\N	\N
20260521130031	{"-- Recreate calendar_entries for tasks that have a planned_date but no linked calendar entry.\n-- These were lost in the earlier dedupe migration.\nINSERT INTO calendar_entries (id, month, year, client_id, art_type, planned_date, designer_id, title, description, task_id, story_quantity)\nSELECT\n  'cal-task-' || t.id AS id,\n  EXTRACT(MONTH FROM (t.planned_date)::timestamptz)::int AS month,\n  EXTRACT(YEAR  FROM (t.planned_date)::timestamptz)::int AS year,\n  t.client_id,\n  t.art_type,\n  t.planned_date,\n  t.assigned_designer_id,\n  t.title,\n  COALESCE(t.description, ''),\n  t.id,\n  CASE WHEN t.art_type = 'Story' THEN COALESCE(t.story_quantity, 1) ELSE NULL END\nFROM tasks t\nWHERE t.planned_date IS NOT NULL\n  AND t.client_id IS NOT NULL\n  AND t.assigned_designer_id IS NOT NULL\n  AND NOT EXISTS (SELECT 1 FROM calendar_entries ce WHERE ce.task_id = t.id)\nON CONFLICT (id) DO NOTHING;"}		renato.cwbranding@gmail.com	\N	\N
20260603205308	{"ALTER TABLE public.client_reports ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'approved'; ALTER TABLE public.client_reports ADD COLUMN IF NOT EXISTS approved_at timestamp with time zone; ALTER TABLE public.client_reports ADD COLUMN IF NOT EXISTS approved_by text;"}		renato.cwbranding@gmail.com	\N	\N
